"""Unified skills, MP readouts and safe party-job customization menus."""

HELPERS = r'''var jobDraft=null,jobDraftHero=null,creatorPartyJobs={...re};
function manaSummaryUI(hero,compact=!1){let mp=Math.max(0,hero.mp??0),max=Math.max(0,hero.maxMp??0);return`<span class="mana-summary ${compact?`compact`:``}" data-hero-mp="${Q(hero.id)}" data-mp="${mp}" data-max-mp="${max}"><span>${mp}<i> / ${max} MP</i></span><span class="mp-track" aria-hidden="true"><span style="width:${max?Math.max(0,Math.min(100,mp/max*100)):0}%"></span></span></span>`}
function skillKindName(skill){return skill.kind===`technique`?`Technique`:`Magic`}
function skillMasteryUI(state,hero,skill){return`Skill Lv ${sLv(state,hero,skill)} · ${state.sp?.[hero.id]?.[skill.id]??0} battle uses`}
function creatorPartyUI(profile){return`<fieldset class="custom-field creator-party-jobs"><legend>Your companions' jobs</legend><p>Choose how Tavin, Iona and Soren fight. Their names and stories remain their own. Jobs can be changed later at a safe shelter.</p>${[`Tavin`,`Iona`,`Soren`].map(id=>`<label><span>${Q(id)}</span><select data-creator-job-hero="${id}" aria-label="${id}'s starting job">${I.map(job=>`<option value="${Q(job.id)}" ${creatorPartyJobs[id]===job.id?`selected`:``}>${Q(job.name)}</option>`).join(``)}</select></label>`).join(``)}</fieldset>`}
function jobsPanelUI(state,heroId){let hero=state.heroes.find(hero=>hero.id===heroId);if(jobDraftHero!==heroId||!I.some(job=>job.id===jobDraft)){jobDraftHero=heroId;jobDraft=hero.job}let preview=jobChangePreview(state,heroId,jobDraft),choice=V(jobDraft),learnable=te.filter(skill=>skill.jobs?.includes(jobDraft)),owned=(state.learnedSpells?.[heroId]??[]),starter=new Set(starterSkillIds(jobDraft));return`${st(state,heroId)}<p class="jobs-intro">Change a traveler's fighting job at a safe shelter. Learned skills stay with that traveler; only skills compatible with the current job can be used. Changing jobs never restores HP or MP.</p><div class="party-job-options" aria-label="Choose ${Q(hero.name)}'s job">${I.map(job=>`<button data-party-job="${Q(job.id)}" aria-pressed="${jobDraft===job.id}" class="${jobDraft===job.id?`chosen`:``}"><strong>${Q(job.name)}</strong><small>${Q(job.trait)}</small></button>`).join(``)}</div><section class="job-preview" data-job-preview="${Q(jobDraft)}"><header><div><span class="eyebrow">${Q(hero.name)} · ${Q(hero.role)} → ${Q(choice.name)}</span><h3>${Q(choice.name)}</h3></div><span>${Q(hero.name)} keeps level ${hero.level}</span></header><p>${Q(choice.description)}</p>${preview?`<dl class="job-preview-stats">${[[`HP`,`${preview.hp} / ${preview.stats.maxHp}`],[`MP`,`${preview.mp} / ${preview.stats.maxMp}`],[`ATK`,preview.stats.attack],[`DEF`,preview.stats.defense],[`MDEF`,preview.stats.magicDefense],[`MAG`,preview.stats.magic]].map(([name,value])=>`<div><dt>${name}</dt><dd>${value}</dd></div>`).join(``)}</dl><h4>Equipment after changing jobs</h4><dl class="job-preview-equipment">${ie.map(slot=>`<div><dt>${Q(EQL[slot]||slot)}</dt><dd>${Q(K(preview.equipment[slot])?.name||`None — equip compatible gear from the pack`)}</dd></div>`).join(``)}</dl>${preview.changes.length?`<p class="jobs-hint">Incompatible equipment returns to the shared pack. Free compatible owned pieces are equipped where possible; no equipment is bought or created.</p>`:`<p class="jobs-hint">Current equipment is compatible with this job.</p>`}<details class="job-preview-catalog"><summary>Skills for this job (${learnable.length})</summary><div class="job-preview-skills">${learnable.map(skill=>`<span><strong>${Q(skill.name)}</strong><small>Lv ${skill.levelRequired} · ${skillCost(skill)} MP · ${owned.includes(skill.id)?`Already learned`:starter.has(skill.id)?`Starter skill`:`Learn at the Skill Shop`}</small></span>`).join(``)}</div></details><div class="job-apply-row"><p>${Q(preview.reason||`Ready to change jobs. Review the equipment and MP above.`)}</p><button class="primary" data-apply-job ${preview.available?``:`disabled`}>Apply ${Q(choice.name)} job</button></div>`:``}</section>`}
function battleSkillsUI(state,hero){let skills=te.filter(skill=>knowsSpell(state,hero,skill));return`<div class="command-heading"><strong>${Q(hero.name)}'s skills <small>${hero.mp} / ${hero.maxMp} MP</small></strong><button data-command="back" class="text-button">← Back</button></div><div class="ability-list">${skills.map(skill=>`<button data-spell="${Q(skill.id)}" data-skill="${Q(skill.id)}" ${canUseSkill(state,hero,skill)?``:`disabled`}><span>${Q(skill.name)} <small>${skillKindName(skill)} · ${skillCost(skill)} MP · ${Q(skillMasteryUI(state,hero,skill))}</small></span><em>${Q(skill.description)}${skill.kind!==`technique`&&hero.status===`silence`?` · Silenced`:``}</em></button>`).join(``)||`<p>No learned skills are available for this job. Visit a Skill Shop.</p>`}</div>`}
'''

SHOP = r'''function magicShopUI(state,heroId){let hero=state.heroes.find(hero=>hero.id===heroId),offers=skillOffers(state,heroId);return`<section class="magic-shop skill-shop"><div class="shop-head"><strong>Skills for ${Q(hero.name)}</strong><span class="shop-gold">${state.gold} gold</span></div>${st(state,heroId)}<p class="shop-intro">${Q(hero.role)} · Level ${hero.level} · ${hero.mp} / ${hero.maxMp} MP. Learn a technique or spell for this traveler's job. Learning never restores MP.</p><div class="shop-list">${offers.map(offer=>{let skill=te.find(skill=>skill.id===(offer.skillId||offer.spellId)),disabled=offer.known||!offer.unlocked||state.gold<offer.price;return`<div class="inventory-row spell-offer" data-skill-offer="${Q(skill.id)}"><span><strong>${Q(skill.name)} <small class="spell-tier-badge">${skillKindName(skill)}</small></strong><small>${Q(skill.description)}</small><small>Lv ${skill.levelRequired} · ${skillCost(skill)} MP · ${offer.known?`Learned by ${Q(hero.name)}`:offer.unlocked?`Ready to learn`:`Requires level ${skill.levelRequired}`}</small></span><span class="spell-price"><strong>${offer.price} G</strong><button class="small-button" data-learn-spell="${Q(skill.id)}" data-learn-skill="${Q(skill.id)}" ${disabled?`disabled`:``}>${offer.known?`Learned`:!offer.unlocked?`Locked`:`Learn`}</button></span></div>`}).join(``)||`<p>No additional skills are offered for this job.</p>`}</div></section>`}
'''

PARTY = r'''function Rt(){let e=X.state,t=e.battle;Z(`party`).innerHTML=e.heroes.map(hero=>{let plan=t?.plans[hero.id],label=plan?plan.type===`spell`?te.find(skill=>skill.id===plan.spellId)?.name??`Skill`:plan.type===`item`?`Item`:plan.type===`guard`?`Guard`:`Attack`:``,ratio=hero.hp/hero.maxHp,set=Lt(hero.id);return`<button class="hero-card ${hero.id===$&&e.mode===`battle`?`selected`:``} ${hero.hp<=0?`fallen`:``}" data-hero="${hero.id}" aria-label="${Q(hero.name)}, level ${hero.level}, ${hero.hp} of ${hero.maxHp} HP, ${hero.mp} of ${hero.maxMp} MP${plan?`, ${Q(label)} planned`:``}"><span class="portrait ${hero.id.toLowerCase()}">${Et(hero.id,48)}</span><span class="hero-detail"><span class="hero-name"><span class="hero-display-name">${Q(hero.name)}</span><span class="hero-level">LV ${hero.level}</span></span><span class="hero-role">${Q(hero.role)} ${hero.status?`<b class="status-tag">${Q(hero.status)}</b>`:``}</span><span class="hp-track"><span style="width:${Math.max(0,ratio*100)}%;background:${ratio<.25?`#cd786e`:`#81aa91`}"></span></span><span class="hero-numbers"><span>${hero.hp}<i> / ${hero.maxHp} HP</i></span></span>${manaSummaryUI(hero,!0)}${plan?`<span class="plan-label">✓ ${Q(label)} queued</span>`:set?`<span class="plan-label">${set}</span>`:``}</span></button>`}).join(``);let low=e.heroes.some(hero=>hero.hp<hero.maxHp*.35||hero.mp<hero.maxMp*.2);Z(`party-note`).textContent=e.mode===`battle`?`Choose for everyone. Then resolve the round.`:low?`Rest at a shelter or inn to recover HP and MP.`:`Avel’s roads connect six regions.`}
'''

STATUS = r'''function ct(e,t,n){let hero=e.heroes.find(hero=>hero.id===t),next=l.xp_thresholds[hero.level];return`${st(e,t)}<div class="status-profile">${n(hero.id,80)}<div><h3>${Y(hero.name)}</h3><p>${Y(hero.role)} · Level ${hero.level}</p><p>${Y(V(hero.job).trait)}</p></div></div><dl class="status-stats">${[[`HP`,`${hero.hp} / ${hero.maxHp}`],[`MP`,`${hero.mp} / ${hero.maxMp}`],[`Attack`,hero.attack],[`Defense`,hero.defense],[`Magic defense`,hero.magicDefense],[`Magic`,hero.magic],[`Accuracy`,hero.accuracy],[`Hits`,hero.hits],[`EXP`,(e.hx?.[hero.id]??e.xp).toLocaleString()],[`Next level`,next===void 0?`MAX`:`${Math.max(0,next-(e.hx?.[hero.id]??e.xp)).toLocaleString()} EXP`]].map(([name,value])=>`<div><dt>${name}</dt><dd>${value}</dd></div>`).join(``)}</dl><h3>Mana</h3>${manaSummaryUI(hero)}<p class="pack-hint">Skills spend MP. Attack and Guard are free; shelters and inns restore MP.</p><h3>Equipment</h3><dl class="equipment-summary">${Object.entries(hero.equipment).map(([slot,id])=>`<div><dt>${Y(slot)}</dt><dd>${Y(K(id)?.name??`None`)}</dd></div>`).join(``)}</dl><p class="pack-hint">${Y(at(e,hero.id))}</p>`}
'''

FIELD = r'''function lt(state,heroId,selectedId){let hero=state.heroes.find(hero=>hero.id===heroId),selected=te.find(skill=>skill.id===selectedId&&knowsSpell(state,hero,skill));if(selected)return`${st(state,heroId)}<div class="command-heading"><strong>${Y(selected.name)} · ${skillCost(selected)} MP · Choose a traveler</strong><button data-field-back>Back</button></div><p>${Y(selected.description)}</p><div class="field-targets">${state.heroes.map(target=>{let valid=selected.effect===`revive`?target.hp===0:target.hp>0&&(selected.effect===`cure`?target.status!==null:target.hp<target.maxHp||selected.id===`daybreak`&&target.status!==null);return`<button data-field-target="${target.id}" ${valid&&canUseSkill(state,hero,selected)?``:`disabled`}><strong>${Y(target.name)}</strong><span>HP ${target.hp} / ${target.maxHp}${target.status?` · `+Y(target.status):``}</span></button>`}).join(``)}</div>`;let learned=te.filter(skill=>knowsSpell(state,hero,skill));return`${st(state,heroId)}${manaSummaryUI(hero)}<p class="muted">Learn techniques and magic at a Skill Shop. Recovery skills can be used on the road; other skills are for battle. Rest at a shelter or inn to restore MP.</p><div class="field-spells skills-library">${learned.map(skill=>{let field=[`heal`,`cure`,`revive`].includes(skill.effect??``);return`<button data-field-spell="${Q(skill.id)}" ${field&&canUseSkill(state,hero,skill)?``:`disabled`}><strong>${Y(skill.name)} <small>${skillCost(skill)} MP</small></strong><small>${skillKindName(skill)} · Lv ${skill.levelRequired} · ${Y(skillMasteryUI(state,hero,skill))}</small><small>${Y(skill.description)}${field?``:` · Battle only`}</small></button>`}).join(``)||`<p>Visit a Skill Shop to learn skills for ${Y(hero.role)}.</p>`}</div>`}
'''

PREP = r'''function depthExpeditionUI(state){let plan=depthPlanForUI(state);if(!plan)return``;let here=dungeonInfo(state.area,state.player.x,state.player.y),info=plan.info,goals=Array.isArray(plan.goals)?plan.goals:[];return`<section class="expedition-plan" data-expedition-plan="${Q(info.root)}"><header><div><span class="eyebrow">${here?`CURRENT EXPEDITION`:`REGIONAL EXPEDITION`}</span><h3>${Q(info.rootName||f[info.root]?.name||info.title)}</h3></div><strong class="depth-floor-label" data-depth-floor="${info.floor}" data-depth-total="${info.total}">${here?`Floor ${info.floor} / ${info.total}`:`${info.total} floors`}</strong></header><p class="expedition-threat">${Q(plan.threat||``)}</p><p>${Q(plan.advice||`Keep enough medicine and MP for the return road.`)}</p><div class="expedition-columns"><section><h4>Pack before descending</h4><div class="expedition-supplies">${(plan.supplies||[]).map(supply=>{let owned=state.inventory[supply.itemId]??0,recommended=supply.quantity??0;return`<div data-expedition-supply="${Q(supply.itemId)}" data-owned="${owned}" data-recommended="${recommended}" class="${owned<recommended?`supply-low`:``}"><span>${Q(K(supply.itemId)?.name||supply.itemId)}</span><strong>${owned} <small>/ ${recommended} suggested</small></strong></div>`}).join(``)}</div><p class="expedition-hint">Suggested reserves are planning guides, never entry requirements. Keep an inn fund and medicine for the way back.</p></section><section><h4>Party reserves</h4><div class="expedition-health">${state.heroes.map(hero=>`<span class="${hero.hp===0||hero.status?`reserve-low`:``}">${Q(hero.name)} · ${hero.hp}/${hero.maxHp} HP${hero.status?` · ${Q(hero.status)}`:``}</span>`).join(``)}</div><div class="expedition-mp">${state.heroes.map(hero=>`<div data-expedition-mp="${Q(hero.id)}" data-remaining="${hero.mp}" data-maximum="${hero.maxMp}" class="${hero.mp<hero.maxMp*.2?`reserve-low`:``}"><strong>${Q(hero.name)}</strong><span>${hero.mp} / ${hero.maxMp} MP</span></div>`).join(``)}</div></section></div><div class="expedition-route"><h4>Route and return</h4><p>${Q(plan.shortcut?.label||`Trace the stairs back to the entrance whenever reserves run low.`)}${plan.shortcut?.open?` <strong>Shortcut open</strong>`:``}</p>${goals.length?`<ul>${goals.map(goal=>`<li>${Q(typeof goal===`string`?goal:goal.text||goal.label||goal.title||``)}</li>`).join(``)}</ul>`:``}<p class="expedition-hint">Train near a safe return, buy for the next threats, then attempt a longer push. Caches are limited; stairs do not restore HP or MP.</p></div></section>`}
'''

SUPPLY = r'''function supplyUseUI(state,hero,itemId){let item=K(itemId),available=consumableValid(state,itemId,hero);return`<button class="small-button" data-use="${Q(itemId)}" ${available?``:`disabled title="No effect on this traveler right now"`} aria-label="Use ${Q(item?.name||itemId)} on ${Q(hero.name)}">Use</button>`}
'''

CSS = r'''
.mana-summary{display:flex;flex-direction:column;gap:5px;font-size:13px;line-height:1.4;color:#e1eaff}.mana-summary i{font-style:normal;color:#bed0f6;font-size:11px}.mana-summary.compact{font-size:11px;gap:4px;margin-top:6px}.mana-summary.compact i{font-size:9px}.mp-track{height:4px;width:100%;background:#071744;border:1px solid #506caa;display:block}.mp-track>span{display:block;height:100%;background:#80a9ec}.party-job-options{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:14px 0}.party-job-options button{display:flex;flex-direction:column;gap:6px;text-align:left;background:#112b70;border:1px solid #728cc5;padding:11px;color:#fff;min-width:0}.party-job-options button.chosen{background:#31549e;border-color:#fff;outline:1px solid #ffdfa0}.party-job-options strong{font-size:14px}.party-job-options small{font-size:10px;line-height:1.6;color:#c8d8f5}.jobs-intro,.jobs-hint{font-size:11px!important;line-height:1.7;color:#c7d9f6}.job-preview{border:1px solid #7790c9;padding:14px;background:#10256580}.job-preview>header{display:flex;justify-content:space-between;gap:12px}.job-preview h3{margin:5px 0;font-size:20px}.job-preview header>span{font-size:10px;color:#c7d9f6;white-space:nowrap}.job-preview>p{font-size:12px;line-height:1.7}.job-preview h4{font-size:12px;margin:18px 0 9px;color:#ffdfa0}.job-preview-stats{display:grid;grid-template-columns:1fr 1fr;gap:0 20px;margin:12px 0}.job-preview-stats>div,.job-preview-equipment>div{display:flex;justify-content:space-between;gap:12px;border-bottom:1px solid #6179b0;padding:7px 0;font-size:11px;line-height:1.6}.job-preview dt{color:#bed1f4}.job-preview dd{margin:0;text-align:right;overflow-wrap:anywhere}.job-preview-equipment{margin:0}.job-preview-catalog{margin-top:16px}.job-preview-catalog>summary{cursor:pointer;font-size:12px;line-height:1.7;color:#ffdfa0}.job-preview-skills{display:grid;gap:7px}.job-preview-skills>span{display:flex;flex-direction:column;gap:3px;font-size:11px;border-bottom:1px solid #6179b0;padding:6px 0}.job-preview-skills strong{font-weight:normal}.job-preview-skills small{color:#c7d9f6;font-size:10px;line-height:1.6}.job-apply-row{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;margin-top:16px}.job-apply-row>p{font-size:11px;line-height:1.6;color:#ffdfa0}.job-apply-row button{flex-shrink:0}.skills-library{margin-top:15px}.skills-library strong>small{font-size:11px;color:#ffdfa0}.expedition-mp{display:grid;gap:7px;margin-top:12px}.expedition-mp>div{display:flex;justify-content:space-between;gap:12px;font-size:11px;line-height:1.6}.expedition-mp strong{font-weight:normal}.creator-party-jobs>p{font-size:11px;line-height:1.7}.creator-party-jobs label{display:flex;justify-content:space-between;align-items:center;gap:15px;margin:9px 0;font-size:12px}.creator-party-jobs select{font:inherit;color:#fff;background:#102764;border:1px solid #849dd1;padding:9px;min-width:160px}.hero-card .hero-detail{min-width:0}
@media(max-width:760px){.party-job-options{gap:6px}.party-job-options button{padding:9px}.party-job-options strong{font-size:12px}.party-job-options small{font-size:9px}.job-preview{padding:11px}.job-preview>header{flex-direction:column;gap:3px}.job-preview h3{font-size:18px}.job-preview-stats{gap:0 14px}.job-preview-stats>div,.job-preview-equipment>div{font-size:10px}.job-apply-row{flex-direction:column;align-items:stretch;gap:8px}.job-apply-row button{width:100%}.mana-summary.compact{font-size:10px;margin-top:5px}.mana-summary.compact i{font-size:8px}.hero-card{min-height:108px}.creator-party-jobs select{min-width:145px;font-size:11px}.expedition-mp>div{font-size:10px}}
'''


def patch(source):
    labels = []

    def once(old, new, label):
        nonlocal source
        count = source.count(old)
        assert count == 1, f'{label}: expected one anchor, found {count}'
        source = source.replace(old, new, 1)
        labels.append(label)

    def function(name, next_name, replacement, label):
        nonlocal source
        start = source.index('function ' + name)
        end = source.index('function ' + next_name, start)
        source = source[:start] + replacement + source[end:]
        labels.append(label)

    once('function magicShopUI(', HELPERS + 'function magicShopUI(', 'MP skill and party-job presentation helpers')
    function('magicShopUI(', 'optionalJournal(', SHOP, 'skill shop offers job techniques and magic with level and MP costs')
    function('Rt()', 'zt()', PARTY, 'every party member shows current and maximum MP')
    function('ct(', 'lt(', STATUS, 'status panel replaces tier charges with mana')
    function('lt(', 'depthWorldMap(', FIELD, 'field skill library uses MP and current-job learning')
    function('depthExpeditionUI(', 'floorSurveyUI(', PREP, 'expedition preparation reports all four MP pools')
    function('supplyUseUI(', 'focusBattleOption(', SUPPLY, 'MP recovery supplies use one clear action')

    old = 'else if(gt===`spells`){let e=te.filter(spell=>knowsSpell(X.state,n,spell));o=`<div class="command-heading"><strong>${Q(Dt($))}\'s magic</strong><button data-command="back" class="text-button">← Back</button></div><div class="ability-list">${e.map(e=>`<button data-spell="${Q(e.id)}" ${!n.charges[e.tier-1]||n.status===`silence`?`disabled`:``}><span>${Q(e.name)} <small>T${e.tier} · ${n.charges[e.tier-1]??0}/${n.maxCharges[e.tier-1]??0} · ${Q(masteryLabel(X.state,n,e))}</small></span><em>${Q(e.description)}</em></button>`).join(``)}</div>`}'
    once(old, 'else if(gt===`spells`)o=battleSkillsUI(e,n);', 'battle skill choices show MP costs and usable techniques while silenced')
    once('<span>✧</span>Magic<small>Spend a tier charge</small>', '<span>✧</span>Skills<small>Spend MP on a technique or spell</small>', 'all jobs have the unified Skills battle command')
    once('[`magic`,`Magic`],[`status`,`Status`]', '[`magic`,`Skills`],[`jobs`,`Jobs`],[`status`,`Status`]', 'party menu exposes skills and all-member job customization')
    once('mt===`status`?(n=`status:`+$,', 'mt===`jobs`?(n=`jobs:`+$,t=Vt(`Party jobs`,`CALLINGS & TRAINING`,jobsPanelUI(e,$),``,`jobs-modal`)):mt===`status`?(n=`status:`+$,', 'job preview and apply use the normal modal boundary')
    once('Vt(`Magic`,`SPELLS & RECOVERY`,lt(e,$,ht))', 'Vt(`Skills`,`TECHNIQUES & MAGIC`,lt(e,$,ht))', 'field skills panel names techniques and magic')
    once('if(t.dataset.learnSpell){', 'if(t.dataset.partyJob){jobDraft=t.dataset.partyJob,jobDraftHero=$,Ht();return}if(t.hasAttribute(`data-apply-job`)){let changed=X.changeJob($,jobDraft);Pt(changed?`${Dt($)} is now a ${V(jobDraft).name}. Review the equipped gear.`:`Change jobs at a safe shelter after finishing the current action.`),Gt();requestAnimationFrame(()=>document.querySelector(`[data-party-job="${jobDraft}"]`)?.focus({preventScroll:!0}));return}if(t.dataset.learnSpell){', 'job choice is previewed before applying its engine-validated change')
    once('X.buySpell($,t.dataset.learnSpell)', 'X.buySkill($,t.dataset.learnSpell)', 'skill shop purchases use the unified skill-learning method')
    once('Check this traveler’s job, spell tier, and gold.', 'Check this traveler’s job, skill level, and gold.', 'skill purchase feedback explains the relevant requirements')
    once('X.useItem(t.dataset.use,$,t.dataset.useTier===void 0?void 0:Number(t.dataset.useTier))', 'X.useItem(t.dataset.use,$)', 'MP tea use no longer selects a charge tier')
    once('function tacticalBattleItemsUI(state,heroId){return[`POTION`,`HIGH_POTION`,`MENDING_BALM`,`ANTIDOTE`,`REVIVAL_SALT`,`CLEAR_TONIC`,`SOOTHING_DRAUGHT`].filter',
         'function tacticalBattleItemsUI(state,heroId){return ue.filter',
         'battle supply selection includes both MP teas from the shared usable-item catalog')

    once('${Ve(e,`cloak`,`Cloak color`)}${n?', '${Ve(e,`cloak`,`Cloak color`)}${creatorPartyUI(e)}${n?', 'new adventures can choose each companion job before beginning')
    once('if(e===`new`&&(kt=structuredClone(R),At=0,Ot=`creator`)',
         'if(e===`new`&&(kt=structuredClone(R),creatorPartyJobs={...re},At=0,Ot=`creator`)',
         'new creation resets companion job drafts')
    once('case`restart`:mt=null,Ot=`creator`,kt=structuredClone(R),At=0,Gt();',
         'case`restart`:mt=null,Ot=`creator`,kt=structuredClone(R),creatorPartyJobs={...re},At=0,Gt();',
         'restarted creation resets companion job drafts')
    once('X.beginAdventure(e)||(Ot=', 'X.beginAdventure(e,{...creatorPartyJobs,Mara:e.job})||(Ot=', 'begin passes the chosen four-member job roster')
    once('let t=e.target;if(t.id!==`hero-name`)return;', 'let t=e.target;if(t.dataset.creatorJobHero){creatorPartyJobs[t.dataset.creatorJobHero]=t.value;return}if(t.id!==`hero-name`)return;', 'native companion job controls update the pending roster')
    once('!(document.activeElement instanceof HTMLInputElement)', '!(document.activeElement instanceof HTMLInputElement)&&!(document.activeElement instanceof HTMLSelectElement)', 'native job selects retain their own arrow-key navigation')

    # Internal IDs stay compatible; the displayed service and resource terms change.
    ui_start = source.index('function at(e,t){')
    source = source[:ui_start] + source[ui_start:].replace('Magic Shop', 'Skill Shop')
    source = source.replace('Learn more spells', 'Learn more skills').replace('learn a spell', 'learn a skill')
    source = source.replace('spell charges', 'MP').replace('spell charge', 'MP').replace('tier charges', 'MP')
    source = source.replace('charges run dry', 'MP runs low').replace('charge recovery', 'MP recovery')
    source = source.replace('SPELLS & RECOVERY', 'SKILLS & RECOVERY').replace('LEARN MAGIC', 'LEARN SKILLS')
    source = source.replace('Jobs change your stats, equipment, spells,', 'Jobs change your stats, equipment, skills,')
    copy_updates = {
        'Elemental spells and a full charge pool.': 'Elemental skills and a large MP pool.',
        'Fewer charges than a specialist.': 'A smaller MP pool than a specialist.',
        'with up to four casts per tier.': 'supported by a balanced MP pool.',
        'keep healing charges for the Bailiff.': 'save MP for healing against the Bailiff.',
        'spending every charge on damage.': 'spending all MP on damage.',
        'does not restore spent charges.': 'does not restore MP.',
        'from the charges saved for the Hart.': 'from the MP saved for the Hart.',
        'Charges persist between encounters.': 'MP persists between encounters.',
        'spends no action, charge or item.': 'spends no action, MP or item.',
        'HP, charges and supplies stay as they are.': 'HP, MP and supplies stay as they are.',
        'Check its charges, supplies, and target.': 'Check MP, supplies, and the target.',
    }
    for old, new in copy_updates.items():
        assert source.count(old) == 1, f'MP copy anchor changed: {old}'
        source = source.replace(old, new, 1)
    labels.append('player-facing shop and resource copy uses skills and MP')
    once('</head>', '<style>' + CSS + '</style>\n</head>', 'responsive MP readouts skill menus and party-job previews')
    return source, labels
